import React, { useEffect, useRef, useState } from 'react';
import {
  Animated,
  Platform,
  StyleSheet,
  Text,
  TouchableOpacity,
  View,
} from 'react-native';
import { MaterialCommunityIcons } from '@expo/vector-icons';

const INSTALL_READY_EVENT = 'worship-pwa-install-ready';

const POSICAO_FIXA_WEB =
  Platform.OS === 'web'
    ? { position: 'fixed' }
    : null;

/*
 * Captura o evento do Chrome o mais cedo possível.
 * O painel nativo somente poderá ser aberto depois
 * que o usuário tocar no botão Instalar.
 */
function registrarEventoGlobalDeInstalacao() {
  if (
    Platform.OS !== 'web' ||
    typeof window === 'undefined' ||
    window.__worshipInstallListenerRegistered
  ) {
    return;
  }

  window.__worshipInstallListenerRegistered = true;

  window.addEventListener('beforeinstallprompt', event => {
    event.preventDefault();

    window.__worshipDeferredInstallPrompt = event;
    window.dispatchEvent(new Event(INSTALL_READY_EVENT));
  });

  window.addEventListener('appinstalled', () => {
    window.__worshipDeferredInstallPrompt = null;

    try {
      window.localStorage.setItem(
        'worship_pwa_installed',
        'true'
      );
    } catch (error) {
      console.log(
        'Não foi possível registrar a instalação:',
        error
      );
    }

    window.dispatchEvent(new Event(INSTALL_READY_EVENT));
  });
}

registrarEventoGlobalDeInstalacao();

function aplicativoEstaInstalado() {
  if (
    Platform.OS !== 'web' ||
    typeof window === 'undefined'
  ) {
    return false;
  }

  const modoStandalone =
    window.matchMedia?.('(display-mode: standalone)')
      ?.matches === true;

  const standaloneIOS =
    window.navigator?.standalone === true;

  return modoStandalone || standaloneIOS;
}

function detectarIOS() {
  if (typeof window === 'undefined') return false;

  const navegador = window.navigator;
  const userAgent = navegador.userAgent || '';

  const dispositivoIOS =
    /iPhone|iPad|iPod/i.test(userAgent);

  const ipadComoMac =
    navegador.platform === 'MacIntel' &&
    navegador.maxTouchPoints > 1;

  return dispositivoIOS || ipadComoMac;
}

function detectarAndroid() {
  if (typeof window === 'undefined') return false;

  return /Android/i.test(
    window.navigator.userAgent || ''
  );
}

function cardFechadoNestaSessao() {
  if (typeof window === 'undefined') return false;

  try {
    return (
      window.sessionStorage.getItem(
        'worship_install_card_closed'
      ) === 'true'
    );
  } catch {
    return false;
  }
}

function registrarFechamentoDaSessao() {
  if (typeof window === 'undefined') return;

  try {
    window.sessionStorage.setItem(
      'worship_install_card_closed',
      'true'
    );
  } catch (error) {
    console.log(
      'Não foi possível registrar o fechamento:',
      error
    );
  }
}

export default function InstallPWAButton() {
  const [visivel, setVisivel] = useState(false);
  const [ehIOS, setEhIOS] = useState(false);
  const [instalando, setInstalando] = useState(false);
  const [mostrarInstrucoes, setMostrarInstrucoes] =
    useState(false);
  const [deferredPrompt, setDeferredPrompt] =
    useState(null);

  const opacidade =
    useRef(new Animated.Value(0)).current;

  const deslocamento =
    useRef(new Animated.Value(35)).current;

  function mostrarCard() {
    if (aplicativoEstaInstalado()) return;

    setVisivel(true);

    opacidade.setValue(0);
    deslocamento.setValue(35);

    Animated.parallel([
      Animated.timing(opacidade, {
        toValue: 1,
        duration: 350,
        useNativeDriver: true,
      }),
      Animated.spring(deslocamento, {
        toValue: 0,
        friction: 8,
        tension: 70,
        useNativeDriver: true,
      }),
    ]).start();
  }

  function esconderCard() {
    registrarFechamentoDaSessao();

    Animated.parallel([
      Animated.timing(opacidade, {
        toValue: 0,
        duration: 220,
        useNativeDriver: true,
      }),
      Animated.timing(deslocamento, {
        toValue: 25,
        duration: 220,
        useNativeDriver: true,
      }),
    ]).start(() => {
      setVisivel(false);
    });
  }

  useEffect(() => {
    if (
      Platform.OS !== 'web' ||
      typeof window === 'undefined' ||
      aplicativoEstaInstalado() ||
      cardFechadoNestaSessao()
    ) {
      return undefined;
    }

    const dispositivoIOS = detectarIOS();
    const dispositivoAndroid = detectarAndroid();

    // O card aparece apenas em celulares e tablets.
    if (!dispositivoIOS && !dispositivoAndroid) {
      return undefined;
    }

    setEhIOS(dispositivoIOS);

    function verificarEventoDeInstalacao() {
      if (aplicativoEstaInstalado()) {
        setVisivel(false);
        return;
      }

      const eventoSalvo =
        window.__worshipDeferredInstallPrompt;

      if (eventoSalvo) {
        setDeferredPrompt(eventoSalvo);
      }
    }

    function aplicativoInstalado() {
      setDeferredPrompt(null);
      setVisivel(false);
    }

    window.addEventListener(
      INSTALL_READY_EVENT,
      verificarEventoDeInstalacao
    );

    window.addEventListener(
      'appinstalled',
      aplicativoInstalado
    );

    /*
     * Mostra o card automaticamente, mesmo que o Chrome
     * ainda não tenha liberado o beforeinstallprompt.
     */
    const temporizador = window.setTimeout(() => {
      verificarEventoDeInstalacao();
      mostrarCard();
    }, 1200);

    return () => {
      window.clearTimeout(temporizador);

      window.removeEventListener(
        INSTALL_READY_EVENT,
        verificarEventoDeInstalacao
      );

      window.removeEventListener(
        'appinstalled',
        aplicativoInstalado
      );
    };
  }, []);

  async function instalarNoAndroid() {
    if (instalando) return;

    const evento =
      deferredPrompt ||
      window.__worshipDeferredInstallPrompt;

    /*
     * Se o Chrome ainda não disponibilizou o painel,
     * apresenta as instruções manuais.
     */
    if (!evento) {
      setMostrarInstrucoes(true);
      return;
    }

    setInstalando(true);

    try {
      await evento.prompt();

      const escolha = await evento.userChoice;

      window.__worshipDeferredInstallPrompt = null;
      setDeferredPrompt(null);

      if (escolha?.outcome === 'accepted') {
        setVisivel(false);
      } else {
        setMostrarInstrucoes(true);
      }
    } catch (error) {
      console.log(
        'Não foi possível abrir a instalação:',
        error
      );

      setMostrarInstrucoes(true);
    } finally {
      setInstalando(false);
    }
  }

  if (
    Platform.OS !== 'web' ||
    !visivel ||
    aplicativoEstaInstalado()
  ) {
    return null;
  }

  return (
    <View
      style={[
        styles.camadaFlutuante,
        POSICAO_FIXA_WEB,
      ]}
      pointerEvents="box-none"
    >
      <Animated.View
        style={[
          styles.card,
          {
            opacity: opacidade,
            transform: [
              { translateY: deslocamento },
            ],
          },
        ]}
      >
        <View style={styles.luzSuperior} />

        <TouchableOpacity
          style={styles.botaoFechar}
          onPress={esconderCard}
          activeOpacity={0.75}
          accessibilityLabel="Fechar aviso de instalação"
        >
          <MaterialCommunityIcons
            name="close"
            size={19}
            color="#A9B8CF"
          />
        </TouchableOpacity>

        <View style={styles.cabecalho}>
          <View style={styles.containerIcone}>
            <MaterialCommunityIcons
              name="download-circle-outline"
              size={32}
              color="#40E0D0"
            />
          </View>

          <View style={styles.areaTitulo}>
            <Text style={styles.destaque}>
              EXPERIÊNCIA COMPLETA
            </Text>

            <Text style={styles.titulo}>
              Instale o WorshipApp
            </Text>
          </View>
        </View>

        <Text style={styles.descricao}>
          Acesse rapidamente pela tela inicial e use o
          WorshipApp com aparência de aplicativo no celular.
        </Text>

        {ehIOS ? (
          <View style={styles.areaInstrucoes}>
            <View style={styles.linhaInstrucao}>
              <View style={styles.numeroInstrucao}>
                <Text style={styles.numeroTexto}>1</Text>
              </View>

              <MaterialCommunityIcons
                name="share-variant-outline"
                size={21}
                color="#40E0D0"
              />

              <Text style={styles.textoInstrucao}>
                Toque no botão Compartilhar do navegador.
              </Text>
            </View>

            <View style={styles.linhaInstrucao}>
              <View style={styles.numeroInstrucao}>
                <Text style={styles.numeroTexto}>2</Text>
              </View>

              <MaterialCommunityIcons
                name="plus-box-outline"
                size={21}
                color="#FFC857"
              />

              <Text style={styles.textoInstrucao}>
                Escolha “Adicionar à Tela de Início”.
              </Text>
            </View>

            <TouchableOpacity
              style={styles.botaoEntendi}
              onPress={esconderCard}
              activeOpacity={0.8}
            >
              <Text style={styles.textoBotaoEntendi}>
                Entendi
              </Text>
            </TouchableOpacity>
          </View>
        ) : (
          <>
            {mostrarInstrucoes && (
              <View style={styles.avisoManual}>
                <MaterialCommunityIcons
                  name="information-outline"
                  size={21}
                  color="#FFC857"
                />

                <Text style={styles.textoAvisoManual}>
                  Abra o menu ⋮ do Chrome e escolha
                  “Instalar aplicativo” ou
                  “Adicionar à tela inicial”.
                </Text>
              </View>
            )}

            <TouchableOpacity
              style={styles.botaoInstalar}
              onPress={instalarNoAndroid}
              disabled={instalando}
              activeOpacity={0.82}
            >
              <MaterialCommunityIcons
                name={
                  instalando
                    ? 'progress-download'
                    : 'download'
                }
                size={21}
                color="#071426"
              />

              <Text style={styles.textoBotaoInstalar}>
                {instalando
                  ? 'Abrindo instalação...'
                  : 'Instalar aplicativo'}
              </Text>
            </TouchableOpacity>

            <TouchableOpacity
              style={styles.botaoAgoraNao}
              onPress={esconderCard}
              activeOpacity={0.75}
            >
              <Text style={styles.textoAgoraNao}>
                Agora não
              </Text>
            </TouchableOpacity>
          </>
        )}
      </Animated.View>
    </View>
  );
}

